package ncasa.expense.infrastructure.household;
import java.util.stream.Collectors;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;import ncasa.household.application.get.GetHouseholdStateForExpensePlansUseCase;import ncasa.household.domain.HouseholdId;
public final class ExpensePlanHouseholdStateAdapter implements ExpensePlanHouseholdStatePort{private final GetHouseholdStateForExpensePlansUseCase household;private final ExpenseCategoryRepository categories;public ExpensePlanHouseholdStateAdapter(GetHouseholdStateForExpensePlansUseCase h,ExpenseCategoryRepository c){household=h;categories=c;}public State get(HouseholdRef id){var state=household.execute(new HouseholdId(id.value()));if(!state.active())return new State(java.util.Set.of(),java.util.Set.of());return new State(state.activeMemberIds().stream().map(MemberRef::new).collect(Collectors.toSet()),categories.findAll(id,false).stream().filter(c->c.status()==ExpenseCategoryStatus.ACTIVE).map(ExpenseCategory::id).collect(Collectors.toSet()));}}
